-- =====================================================================
-- Findout Jornada · Migration 0013 · Revisão do banco + 2 seções novas por matéria (528 questões)
-- Rodar no SQL Editor do Supabase depois da 0012. Idempotente: pode rodar de novo.
--
-- Parte 1 · Correções da revisão das 796 questões existentes:
--   · 8 questões quase idênticas a outras de unidades diferentes são trocadas por questões novas
--   · 1 enunciado impreciso corrigido (BRICS: a África do Sul entrou em 2011, não na formação)
-- Parte 2 · 20 seções novas (2 por matéria), 40 unidades, 88 lições e 528 questões em estilo ENEM.
-- Depois de rodar, abra o painel: ele publica a nova versão sozinho.
-- =====================================================================

create or replace function public.fj_seed_q(p_mat text, p_uni text, p_lic text, p_ordem int, p_tipo text, p_enun text, p_dados jsonb, p_expl text, p_dif int default 2)
returns void language plpgsql as $$
declare uni uuid := md5('uni:' || p_uni)::uuid; lic uuid := md5('lic:' || p_lic)::uuid; qid uuid := md5('q:' || p_lic || '|' || p_enun)::uuid;
begin
  insert into public.questoes (id, materia_id, unidade_id, tipo, enunciado, dados, explicacao, status)
  values (qid, p_mat, uni, p_tipo, p_enun, p_dados || jsonb_build_object('dificuldade', p_dif), p_expl, 'publicada')
  on conflict (id) do nothing;
  insert into public.licao_questoes (licao_id, questao_id, ordem) values (lic, qid, p_ordem) on conflict do nothing;
end $$;

-- ---------------------------------------------------------------
-- PARTE 1 · Correções
-- ---------------------------------------------------------------
-- BRICS: "formado originalmente por" -> "formado por"
update public.questoes set enunciado = 'O grupo BRICS é formado por:' where id = md5('q:geo:ordemmundial:2|O grupo BRICS foi formado originalmente por:')::uuid;

-- Questões repetidas (mesmo conteúdo de outra unidade): saem e entram substitutas na mesma lição
delete from public.questoes where id in (
  md5('q:red:dissertativo:2|Os cinco elementos da proposta de intervenção completa no ENEM são:')::uuid,
  md5('q:red:dissertativo:2|Esta afirmação está certa?')::uuid,
  md5('q:red:dissertativo:2|Associe o elemento da proposta à pergunta que ele responde')::uuid,
  md5('q:ing:sentido:2|A palavra "actually" costuma confundir estudantes brasileiros porque significa:')::uuid,
  md5('q:ing:sentido:2|Associe o falso cognato à sua tradução correta')::uuid,
  md5('q:fil:sociologia:1|Para Marx, a história das sociedades é movida pela:')::uuid,
  md5('q:fil:filosofia:2|Para Kant, agir moralmente é agir por:')::uuid,
  md5('q:geo:industria:2|A principal fonte de geração de energia elétrica no Brasil é a:')::uuid
);
select public.fj_seed_q('red', 'red:dissertativo', 'red:dissertativo:2', 0, 'mc', $q$Na proposta "o governo deve criar programas de capacitação, por meio de parcerias com universidades, para reduzir o desemprego juvenil, garantindo bolsas aos participantes", o trecho "garantindo bolsas aos participantes" corresponde ao elemento:$q$, $j${"opts":["Detalhamento","Agente","Meio","Finalidade"],"a":0}$j$, $q$O detalhamento aprofunda um dos elementos: aqui, especifica como a ação será viabilizada.$q$, 2);
select public.fj_seed_q('red', 'red:dissertativo', 'red:dissertativo:2', 2, 'tf', $q$Esta afirmação está certa?$q$, $j${"stmt":"Na proposta de intervenção, o agente pode ser o Estado, a escola, a mídia, a família ou a própria sociedade civil.","a":true}$j$, $q$Verdadeiro: o agente é quem executa a ação, e pode ser qualquer instituição ou grupo capaz de agir sobre o problema.$q$, 1);
select public.fj_seed_q('red', 'red:dissertativo', 'red:dissertativo:2', 3, 'order', $q$Ordene os elementos na sequência em que aparecem na proposta "O Ministério da Saúde deve ampliar o atendimento psicológico, por meio de contratação de profissionais, a fim de reduzir a ansiedade entre jovens"$q$, $j${"items":["Agente: o Ministério da Saúde","Ação: ampliar o atendimento psicológico","Meio: contratação de profissionais","Finalidade: reduzir a ansiedade entre jovens"]}$j$, $q$Quem, o quê, como e para quê: a ordem clássica da proposta de intervenção.$q$, 2);
select public.fj_seed_q('ing', 'ing:sentido', 'ing:sentido:2', 0, 'mc', $q$Na frase "All students must attend the meeting", o verbo "attend" significa:$q$, $j${"opts":["Participar de, comparecer a","Atender ao telefone","Esperar por","Cancelar"],"a":0}$j$, $q$Attend é falso cognato: significa comparecer; atender ao telefone é answer the phone.$q$, 2);
select public.fj_seed_q('ing', 'ing:sentido', 'ing:sentido:2', 3, 'match', $q$Associe o falso cognato à sua tradução correta$q$, $j${"pairs":[["lunch","almoço"],["notice","aviso, perceber"],["realize","perceber, dar-se conta"],["exquisite","requintado"]]}$j$, $q$Lunch não é lanche, notice não é notícia, realize não é realizar e exquisite não é esquisito.$q$, 2);
select public.fj_seed_q('fil', 'fil:sociologia', 'fil:sociologia:1', 1, 'mc', $q$Para Durkheim, a solidariedade orgânica, típica das sociedades modernas, nasce:$q$, $j${"opts":["Da divisão do trabalho, que torna as pessoas interdependentes","Da semelhança total entre os indivíduos","Da ausência de regras sociais","Do isolamento das famílias no campo"],"a":0}$j$, $q$Na solidariedade orgânica, cada um faz uma parte e todos dependem uns dos outros, como os órgãos de um corpo.$q$, 2);
select public.fj_seed_q('fil', 'fil:filosofia', 'fil:filosofia:2', 1, 'mc', $q$Ao declarar que "Deus está morto", Nietzsche quis dizer que:$q$, $j${"opts":["Os valores tradicionais que davam sentido à vida perderam a força na modernidade","A religião havia sido proibida por lei na Europa","A ciência provou a inexistência de qualquer divindade","Os templos deveriam ser fechados"],"a":0}$j$, $q$A frase é um diagnóstico cultural: sem os antigos fundamentos, o ser humano precisa criar os próprios valores.$q$, 3);
select public.fj_seed_q('geo', 'geo:industria', 'geo:industria:2', 0, 'mc', $q$A Zona Franca de Manaus, criada em 1967, atraiu indústrias para a Amazônia principalmente por meio de:$q$, $j${"opts":["Incentivos fiscais, como isenção de impostos","Proibição de fábricas nas demais regiões","Oferta de energia nuclear barata","Ligação ferroviária com São Paulo"],"a":0}$j$, $q$A isenção de tributos fez da Zona Franca um polo de eletrônicos e motocicletas no meio da floresta.$q$, 2);

