-- ---------------------------------------------------------------
-- MATEMÁTICA · Funções e gráficos / Grandezas, medidas e leitura de dados
-- ---------------------------------------------------------------
-- mat:funcao1:1 · O que é uma função
select public.fj_seed_q('mat', 'mat:funcao1', 'mat:funcao1:1', 0, 'mc', $q$Uma corrida de táxi custa R$ 5,00 de bandeirada mais R$ 2,50 por quilômetro. A lei que dá o preço P em função dos quilômetros x é:$q$, $j${"opts":["P = 5 + 2,5x","P = 2,5 + 5x","P = 7,5x","P = 5x + 2,5x"],"a":0}$j$, $q$O valor fixo (5) soma-se ao valor que depende da distância (2,5 por km): P = 5 + 2,5x.$q$, 1);
select public.fj_seed_q('mat', 'mat:funcao1', 'mat:funcao1:1', 1, 'mc', $q$Se f(x) = 3x − 4, quanto vale f(5)?$q$, $j${"opts":["11","19","1","15"],"a":0}$j$, $q$Basta substituir: 3 × 5 − 4 = 15 − 4 = 11.$q$, 1);
select public.fj_seed_q('mat', 'mat:funcao1', 'mat:funcao1:1', 2, 'mc', $q$Em uma função, a variável independente é aquela que:$q$, $j${"opts":["Escolhemos livremente, e dela depende o resultado","Sempre vale zero","É calculada a partir da outra","Nunca aparece no gráfico"],"a":0}$j$, $q$Na função P = 5 + 2,5x, escolhemos x (independente) e obtemos P (dependente).$q$, 1);
select public.fj_seed_q('mat', 'mat:funcao1', 'mat:funcao1:1', 3, 'tf', $q$Julgue a afirmação sobre funções$q$, $j${"stmt":"Em uma função, cada valor de x pode ter apenas um valor de y correspondente.","a":true}$j$, $q$Verdadeiro: essa é a definição de função. Um mesmo x não pode gerar dois resultados diferentes.$q$, 2);
select public.fj_seed_q('mat', 'mat:funcao1', 'mat:funcao1:1', 4, 'bank', $q$Complete a frase sobre a função f(x) = 2x + 1$q$, $j${"parts":["Na função f(x) = 2x + 1, o valor de f(0) é ",", e f(x) = 7 acontece quando x vale ","."],"a":["1","3"],"extra":["2","4"]}$j$, $q$f(0) = 2 × 0 + 1 = 1. Para f(x) = 7: 2x + 1 = 7, logo x = 3.$q$, 2);
select public.fj_seed_q('mat', 'mat:funcao1', 'mat:funcao1:1', 5, 'match', $q$Associe cada situação à sua lei de formação$q$, $j${"pairs":[["Plano de celular: R$ 30 fixos mais R$ 0,50 por minuto","y = 30 + 0,5x"],["Pagamento de R$ 12 por hora trabalhada","y = 12x"],["Tanque com 50 L que perde 2 L por hora","y = 50 − 2x"],["Preço com desconto de 20%","y = 0,8x"]]}$j$, $q$Valor fixo mais variável, só variável, decrescente e proporcional: cada situação gera uma lei diferente.$q$, 2);
-- mat:funcao1:2 · Reta no plano
select public.fj_seed_q('mat', 'mat:funcao1', 'mat:funcao1:2', 0, 'mc', $q$Na função f(x) = 2x + 6, o ponto em que o gráfico corta o eixo y é:$q$, $j${"opts":["(0, 6)","(6, 0)","(0, 2)","(−3, 0)"],"a":0}$j$, $q$O gráfico corta o eixo y quando x = 0: f(0) = 6. O coeficiente linear é 6.$q$, 2);
select public.fj_seed_q('mat', 'mat:funcao1', 'mat:funcao1:2', 1, 'mc', $q$O zero (ou raiz) da função f(x) = 2x + 6 é:$q$, $j${"opts":["x = −3","x = 3","x = 6","x = 0"],"a":0}$j$, $q$Zero da função é o x que faz f(x) = 0: 2x + 6 = 0, logo x = −3.$q$, 2);
select public.fj_seed_q('mat', 'mat:funcao1', 'mat:funcao1:2', 2, 'mc', $q$A função f(x) = −4x + 1 é decrescente porque:$q$, $j${"opts":["O coeficiente angular é negativo","O coeficiente linear é positivo","Seu gráfico passa pela origem","Ela tem duas raízes"],"a":0}$j$, $q$O sinal do coeficiente de x (angular) decide: negativo, a reta desce; positivo, sobe.$q$, 2);
select public.fj_seed_q('mat', 'mat:funcao1', 'mat:funcao1:2', 3, 'tf', $q$Julgue a afirmação sobre o gráfico$q$, $j${"stmt":"O gráfico de toda função do 1º grau é uma reta.","a":true}$j$, $q$Verdadeiro: por isso ela também é chamada de função afim ou linear, e bastam dois pontos para traçá-la.$q$, 1);
select public.fj_seed_q('mat', 'mat:funcao1', 'mat:funcao1:2', 4, 'order', $q$Ordene os passos para desenhar o gráfico de f(x) = x − 2$q$, $j${"items":["Calcular f(0) = −2 e marcar o ponto (0, −2)","Calcular f(2) = 0 e marcar o ponto (2, 0)","Traçar a reta que passa pelos dois pontos","Conferir que a reta sobe, pois o coeficiente angular é positivo"]}$j$, $q$Dois pontos bastam para uma reta; o sinal do coeficiente angular confirma a inclinação.$q$, 2);
select public.fj_seed_q('mat', 'mat:funcao1', 'mat:funcao1:2', 5, 'match', $q$Associe a função ao comportamento do seu gráfico$q$, $j${"pairs":[["f(x) = 3x − 1","Reta crescente"],["f(x) = −2x + 5","Reta decrescente"],["f(x) = 4","Reta horizontal"],["f(x) = x","Reta pela origem com inclinação 45°"]]}$j$, $q$Coeficiente positivo sobe, negativo desce, zero fica horizontal e f(x) = x passa pela origem.$q$, 2);
-- mat:funcao1:3 · Problemas com função afim
select public.fj_seed_q('mat', 'mat:funcao1', 'mat:funcao1:3', 0, 'mc', $q$Uma conta de luz tem taxa fixa de R$ 20 e cobra R$ 0,80 por kWh. Uma família que consumiu 150 kWh pagará:$q$, $j${"opts":["R$ 140","R$ 120","R$ 170","R$ 100"],"a":0}$j$, $q$P = 20 + 0,8 × 150 = 20 + 120 = R$ 140.$q$, 2);
select public.fj_seed_q('mat', 'mat:funcao1', 'mat:funcao1:3', 1, 'mc', $q$Um vendedor recebe R$ 1.200 fixos mais R$ 50 por produto vendido. Quantos produtos precisa vender para ganhar R$ 2.000?$q$, $j${"opts":["16","40","20","8"],"a":0}$j$, $q$1.200 + 50x = 2.000, então 50x = 800 e x = 16 produtos.$q$, 2);
select public.fj_seed_q('mat', 'mat:funcao1', 'mat:funcao1:3', 2, 'mc', $q$Uma vela de 20 cm queima 2 cm por hora. Depois de quantas horas ela terá 8 cm?$q$, $j${"opts":["6 horas","4 horas","10 horas","12 horas"],"a":0}$j$, $q$Altura = 20 − 2t. Para 8 cm: 20 − 2t = 8, logo t = 6 horas.$q$, 2);
select public.fj_seed_q('mat', 'mat:funcao1', 'mat:funcao1:3', 3, 'tf', $q$Julgue a afirmação sobre o problema$q$, $j${"stmt":"Se o plano A custa R$ 40 fixos mais R$ 1 por GB e o plano B custa R$ 2 por GB sem taxa fixa, os dois custam o mesmo quando o consumo é de 40 GB.","a":true}$j$, $q$Verdadeiro: 40 + x = 2x leva a x = 40 GB. Abaixo disso o B é mais barato; acima, o A.$q$, 3);
select public.fj_seed_q('mat', 'mat:funcao1', 'mat:funcao1:3', 4, 'bank', $q$Complete a frase sobre o aluguel de bicicleta$q$, $j${"parts":["Um aluguel de bicicleta cobra R$ 10 fixos mais R$ 3 por hora. Por 4 horas paga-se R$ "," e, com R$ 40, é possível pedalar por "," horas."],"a":["22","10"],"extra":["12","13"]}$j$, $q$10 + 3 × 4 = 22. Com 40 reais: 10 + 3h = 40, logo h = 10 horas.$q$, 2);
select public.fj_seed_q('mat', 'mat:funcao1', 'mat:funcao1:3', 5, 'order', $q$Ordene as etapas para resolver: "A temperatura de um forno sobe 15 °C por minuto a partir de 25 °C. Quando chega a 205 °C?"$q$, $j${"items":["Escrever a lei: T = 25 + 15t","Igualar a lei ao valor pedido: 25 + 15t = 205","Isolar t: 15t = 180","Concluir: t = 12 minutos"]}$j$, $q$Montar a função, igualar ao valor final e resolver a equação do 1º grau.$q$, 2);
-- mat:funcao2:1 · Parábola e raízes
select public.fj_seed_q('mat', 'mat:funcao2', 'mat:funcao2:1', 0, 'mc', $q$O gráfico da função f(x) = x² − 4 é uma parábola que:$q$, $j${"opts":["Tem concavidade para cima e corta o eixo x em −2 e 2","Tem concavidade para baixo e não corta o eixo x","É uma reta decrescente","Corta o eixo x apenas em x = 4"],"a":0}$j$, $q$O coeficiente de x² é positivo (concavidade para cima); x² − 4 = 0 dá x = 2 ou x = −2.$q$, 2);
select public.fj_seed_q('mat', 'mat:funcao2', 'mat:funcao2:1', 1, 'mc', $q$As raízes da equação x² − 5x + 6 = 0 são:$q$, $j${"opts":["2 e 3","−2 e −3","1 e 6","5 e 6"],"a":0}$j$, $q$Dois números que somam 5 e multiplicam 6: 2 e 3. Conferindo: 2² − 10 + 6 = 0.$q$, 2);
select public.fj_seed_q('mat', 'mat:funcao2', 'mat:funcao2:1', 2, 'mc', $q$Na função f(x) = −x² + 2x + 3, a concavidade da parábola é:$q$, $j${"opts":["Para baixo, pois o coeficiente de x² é negativo","Para cima, pois o termo independente é positivo","Para cima, pois o coeficiente de x é positivo","Não existe parábola, pois há sinal negativo"],"a":0}$j$, $q$Quem decide a concavidade é o sinal de a, o coeficiente de x²: aqui a = −1, logo para baixo.$q$, 1);
select public.fj_seed_q('mat', 'mat:funcao2', 'mat:funcao2:1', 3, 'tf', $q$Julgue a afirmação sobre o discriminante$q$, $j${"stmt":"Quando o discriminante Δ = b² − 4ac é negativo, a parábola não toca o eixo x.","a":true}$j$, $q$Verdadeiro: Δ negativo significa que não há raízes reais, então o gráfico fica todo acima ou todo abaixo do eixo x.$q$, 2);
select public.fj_seed_q('mat', 'mat:funcao2', 'mat:funcao2:1', 4, 'bank', $q$Complete a frase sobre a equação x² − 9 = 0$q$, $j${"parts":["A equação x² − 9 = 0 tem as raízes 3 e ",", e o vértice da parábola y = x² − 9 fica no ponto (0, ",")."],"a":["−3","−9"],"extra":["9","0"]}$j$, $q$x² = 9 dá x = 3 ou x = −3. Como a parábola é simétrica, o vértice está em x = 0, onde y = −9.$q$, 2);
select public.fj_seed_q('mat', 'mat:funcao2', 'mat:funcao2:1', 5, 'match', $q$Associe cada valor de Δ à quantidade de raízes reais$q$, $j${"pairs":[["Δ > 0","Duas raízes reais diferentes"],["Δ = 0","Uma raiz real (dupla)"],["Δ < 0","Nenhuma raiz real"],["Δ = b² − 4ac","Fórmula do discriminante"]]}$j$, $q$O discriminante diz quantas vezes a parábola corta o eixo x.$q$, 2);
-- mat:funcao2:2 · Máximos e mínimos
select public.fj_seed_q('mat', 'mat:funcao2', 'mat:funcao2:2', 0, 'mc', $q$A altura de uma bola é dada por h(t) = −5t² + 20t. A altura máxima é atingida em:$q$, $j${"opts":["t = 2 s","t = 4 s","t = 20 s","t = 5 s"],"a":0}$j$, $q$O instante do vértice é t = −b/(2a) = −20/(2 × (−5)) = 2 s.$q$, 2);
select public.fj_seed_q('mat', 'mat:funcao2', 'mat:funcao2:2', 1, 'mc', $q$Ainda para h(t) = −5t² + 20t, a altura máxima da bola é:$q$, $j${"opts":["20 m","10 m","40 m","2 m"],"a":0}$j$, $q$Em t = 2: h = −5 × 4 + 20 × 2 = −20 + 40 = 20 m.$q$, 2);
select public.fj_seed_q('mat', 'mat:funcao2', 'mat:funcao2:2', 2, 'mc', $q$O lucro de uma loja é L(x) = −x² + 60x − 500, com x unidades vendidas. Quantas unidades dão o lucro máximo?$q$, $j${"opts":["30","60","500","15"],"a":0}$j$, $q$x do vértice = −b/(2a) = −60/(−2) = 30 unidades.$q$, 3);
select public.fj_seed_q('mat', 'mat:funcao2', 'mat:funcao2:2', 3, 'tf', $q$Julgue a afirmação sobre o vértice$q$, $j${"stmt":"Se a parábola tem concavidade para cima, o vértice é o ponto de valor mínimo da função.","a":true}$j$, $q$Verdadeiro: concavidade para cima, o vértice é o ponto mais baixo; para baixo, é o mais alto.$q$, 1);
select public.fj_seed_q('mat', 'mat:funcao2', 'mat:funcao2:2', 4, 'order', $q$Ordene os passos para achar o ponto mais alto de uma parábola com a < 0$q$, $j${"items":["Identificar os coeficientes a, b e c","Calcular o x do vértice: x = −b / (2a)","Substituir esse x na função para achar o y do vértice","Interpretar: o y do vértice é o valor máximo"]}$j$, $q$Primeiro o x do vértice, depois o y: ele é o máximo quando a concavidade é para baixo.$q$, 2);
select public.fj_seed_q('mat', 'mat:funcao2', 'mat:funcao2:2', 5, 'bank', $q$Complete a frase sobre o cercado$q$, $j${"parts":["Com 40 m de cerca, o retângulo de maior área tem lados de "," m e área de "," m²."],"a":["10","100"],"extra":["20","400"]}$j$, $q$Área = x(20 − x) = −x² + 20x, máxima em x = 10: um quadrado de 10 m por 10 m, área 100 m².$q$, 3);
-- mat:funcao2:3 · Crescimento exponencial
select public.fj_seed_q('mat', 'mat:funcao2', 'mat:funcao2:3', 0, 'mc', $q$Uma bactéria dobra a cada hora. Começando com 100 bactérias, quantas haverá após 4 horas?$q$, $j${"opts":["1.600","400","800","3.200"],"a":0}$j$, $q$100 × 2⁴ = 100 × 16 = 1.600 bactérias.$q$, 2);
select public.fj_seed_q('mat', 'mat:funcao2', 'mat:funcao2:3', 1, 'mc', $q$A função N(t) = 500 × 1,1ᵗ descreve uma população que:$q$, $j${"opts":["Cresce 10% a cada período","Cresce 500 a cada período","Diminui 10% a cada período","Dobra a cada período"],"a":0}$j$, $q$Multiplicar por 1,1 a cada período é aumentar 10% sobre o valor anterior.$q$, 2);
select public.fj_seed_q('mat', 'mat:funcao2', 'mat:funcao2:3', 2, 'mc', $q$Um carro perde 20% do valor por ano. Se custa R$ 50.000, valerá após 2 anos:$q$, $j${"opts":["R$ 32.000","R$ 30.000","R$ 40.000","R$ 20.000"],"a":0}$j$, $q$Perder 20% é multiplicar por 0,8: 50.000 × 0,8 × 0,8 = R$ 32.000.$q$, 2);
select public.fj_seed_q('mat', 'mat:funcao2', 'mat:funcao2:3', 3, 'tf', $q$Julgue a afirmação sobre exponenciais$q$, $j${"stmt":"Em um crescimento exponencial, a quantidade aumenta sempre a mesma porcentagem por período, e não o mesmo valor.","a":true}$j$, $q$Verdadeiro: é a diferença para o crescimento linear, que soma o mesmo valor a cada período.$q$, 2);
select public.fj_seed_q('mat', 'mat:funcao2', 'mat:funcao2:3', 4, 'order', $q$Ordene do menor para o maior valor após 3 períodos, partindo de 100$q$, $j${"items":["Perde metade a cada período (12,5)","Cresce 10 por período (130)","Cresce 50% por período (337,5)","Dobra a cada período (800)"]}$j$, $q$12,5 < 130 < 337,5 < 800: o linear fica para trás das exponenciais crescentes.$q$, 3);
select public.fj_seed_q('mat', 'mat:funcao2', 'mat:funcao2:3', 5, 'bank', $q$Complete a frase sobre a meia-vida$q$, $j${"parts":["Se uma substância tem meia-vida de 10 anos, após 20 anos restará ","% da quantidade inicial e, após 30 anos, ","%."],"a":["25","12,5"],"extra":["50","0"]}$j$, $q$A cada 10 anos a quantidade cai pela metade: 100% → 50% → 25% → 12,5%.$q$, 3);
