select public.fj_seed_q('mat', 'mat:unidades', 'mat:unidades:1', 2, 'mc', $q$Uma corrida de rua tem 21 km. Em metros, são:$q$, $j${"opts":["21.000 m","2.100 m","210 m","210.000 m"],"a":0}$j$, $q$1 km = 1.000 m, portanto 21 km = 21.000 m.$q$, 1);
