select public.fj_seed_q('por', 'por:inferencia', 'por:inferencia:3', 4, 'match', $q$Associe cada frase à sua classificação$q$, $j${"pairs":[["A cidade tem 500 mil habitantes","Fato"],["A cidade é a mais agradável do estado","Opinião"],["Compre agora e economize","Intenção persuasiva"],["Como diz o ditado, quem espera sempre alcança","Senso comum"]]}$j$, $q$Dado verificável, julgamento, apelo e saber popular: quatro tipos de enunciado.$q$, 2);
