select public.fj_seed_q('bio', 'bio:plantas', 'bio:plantas:1', 0, 'mc', $q$Na fotossíntese, a planta usa luz, água e gás carbônico para produzir:$q$, $j${"opts":["Glicose e oxigênio","Proteínas e nitrogênio","Gás carbônico e água","Sais minerais e calor"],"a":0}$j$, $q$6 CO₂ + 6 H₂O + luz → C₆H₁₂O₆ + 6 O₂: a planta fabrica açúcar e libera oxigênio.$q$, 1);
select public.fj_seed_q('bio', 'bio:plantas', 'bio:plantas:1', 1, 'mc', $q$O pigmento que capta a energia da luz nas folhas é a:$q$, $j${"opts":["Clorofila","Hemoglobina","Melanina","Queratina"],"a":0}$j$, $q$A clorofila, nos cloroplastos, absorve principalmente luz vermelha e azul e reflete o verde.$q$, 1);
