select public.fj_seed_q('bio', 'bio:animais', 'bio:animais:1', 5, 'order', $q$Ordene as etapas do ciclo de vida da borboleta$q$, $j${"items":["Ovo","Lagarta (larva)","Pupa (casulo)","Adulto"]}$j$, $q$É a metamorfose completa, típica de borboletas, besouros e mosquitos.$q$, 1);
