select public.fj_seed_q('bio', 'bio:animais', 'bio:animais:2', 0, 'mc', $q$Os anfíbios, como sapos e rãs, dependem da água porque:$q$, $j${"opts":["Suas larvas (girinos) vivem na água e sua pele precisa ficar úmida","Não conseguem andar em terra firme","Têm escamas que ressecam no sol","Põem ovos com casca dura"],"a":0}$j$, $q$Anfíbio significa duas vidas: girino aquático e adulto que respira também pela pele úmida.$q$, 2);
select public.fj_seed_q('bio', 'bio:animais', 'bio:animais:2', 1, 'mc', $q$Os répteis conseguiram conquistar ambientes secos principalmente graças:$q$, $j${"opts":["À pele seca com escamas e ao ovo com casca","À respiração por brânquias","À temperatura corporal constante","À ausência de pulmões"],"a":0}$j$, $q$Escamas evitam a perda de água e o ovo com casca dispensa o ambiente aquático para se reproduzir.$q$, 2);
select public.fj_seed_q('bio', 'bio:animais', 'bio:animais:2', 2, 'mc', $q$Aves e mamíferos são chamados de endotérmicos (ou homeotérmicos) porque:$q$, $j${"opts":["Mantêm a temperatura do corpo constante, produzindo calor internamente","Dependem do sol para se aquecer","Vivem apenas em regiões quentes","Têm sangue frio como os peixes"],"a":0}$j$, $q$Manter o corpo aquecido permite viver em climas frios, mas exige comer mais.$q$, 2);
