select public.fj_seed_q('bio', 'bio:nervoso', 'bio:nervoso:1', 0, 'mc', $q$A célula responsável por transmitir impulsos nervosos é o:$q$, $j${"opts":["Neurônio","Hemácia","Osteócito","Miócito"],"a":0}$j$, $q$O neurônio tem dendritos (recebem), corpo celular e axônio (transmite o impulso).$q$, 1);
select public.fj_seed_q('bio', 'bio:nervoso', 'bio:nervoso:1', 1, 'mc', $q$Ao encostar a mão em uma panela quente, a pessoa a retira antes mesmo de sentir dor. Isso acontece porque:$q$, $j${"opts":["O reflexo é comandado pela medula espinhal, sem passar pelo cérebro","O cérebro envia o comando em menos de um milésimo de segundo","Os músculos da mão agem sozinhos, sem nervos","A pele não tem receptores de dor"],"a":0}$j$, $q$No arco reflexo, o impulso vai do receptor à medula e volta ao músculo; o cérebro é avisado depois.$q$, 2);
select public.fj_seed_q('bio', 'bio:nervoso', 'bio:nervoso:1', 2, 'mc', $q$A sinapse é:$q$, $j${"opts":["A região de comunicação entre um neurônio e outra célula, por neurotransmissores","O núcleo do neurônio","A capa de gordura que envolve o axônio","Um tipo de célula do sangue"],"a":0}$j$, $q$Na sinapse, o neurônio libera substâncias químicas (neurotransmissores) que passam a mensagem adiante.$q$, 2);
select public.fj_seed_q('bio', 'bio:nervoso', 'bio:nervoso:1', 3, 'tf', $q$Julgue a afirmação sobre o cérebro$q$, $j${"stmt":"O cerebelo é a parte do encéfalo responsável principalmente pela coordenação dos movimentos e pelo equilíbrio.","a":true}$j$, $q$Verdadeiro: o álcool afeta o cerebelo, por isso o andar cambaleante.$q$, 2);
select public.fj_seed_q('bio', 'bio:nervoso', 'bio:nervoso:1', 4, 'order', $q$Ordene o caminho do impulso no arco reflexo$q$, $j${"items":["O receptor na pele detecta o estímulo","O neurônio sensitivo leva o impulso à medula","A medula processa e envia a resposta pelo neurônio motor","O músculo contrai e afasta a mão"]}$j$, $q$Receptor, via sensitiva, medula, via motora e músculo: resposta rápida sem o cérebro.$q$, 2);
select public.fj_seed_q('bio', 'bio:nervoso', 'bio:nervoso:1', 5, 'match', $q$Associe a parte do sistema nervoso à sua função$q$, $j${"pairs":[["Cérebro","Pensamento, memória e sentidos"],["Cerebelo","Equilíbrio e coordenação motora"],["Bulbo","Controle da respiração e dos batimentos"],["Medula espinhal","Reflexos e condução de impulsos"]]}$j$, $q$Cada região do sistema nervoso central tem funções específicas.$q$, 2);
