-- fis:hidrostatica:1 · Pressão e densidade
select public.fj_seed_q('fis', 'fis:hidrostatica', 'fis:hidrostatica:1', 0, 'mc', $q$Uma faca afiada corta melhor que uma cega porque:$q$, $j${"opts":["A mesma força se concentra em uma área menor, aumentando a pressão","A lâmina fina tem mais massa","O aço afiado é mais quente","A gravidade age mais sobre lâminas finas"],"a":0}$j$, $q$Pressão = força ÷ área. Área menor, pressão maior.$q$, 1);
select public.fj_seed_q('fis', 'fis:hidrostatica', 'fis:hidrostatica:1', 1, 'mc', $q$Um bloco de 2 kg ocupa 0,001 m³ (1 litro). Sua densidade é:$q$, $j${"opts":["2.000 kg/m³","0,002 kg/m³","2 kg/m³","200 kg/m³"],"a":0}$j$, $q$d = m ÷ V = 2 ÷ 0,001 = 2.000 kg/m³, o dobro da água.$q$, 2);
select public.fj_seed_q('fis', 'fis:hidrostatica', 'fis:hidrostatica:1', 2, 'mc', $q$Ao mergulhar fundo em uma piscina, sentimos os ouvidos doerem porque:$q$, $j${"opts":["A pressão da água aumenta com a profundidade","A água fica mais fria no fundo","A água do fundo é menos densa","O som se propaga mal na água"],"a":0}$j$, $q$A cada 10 m de água, a pressão aumenta cerca de 1 atm.$q$, 1);
select public.fj_seed_q('fis', 'fis:hidrostatica', 'fis:hidrostatica:1', 3, 'tf', $q$Julgue a afirmação sobre pressão atmosférica$q$, $j${"stmt":"No alto de uma montanha, a pressão atmosférica é menor que ao nível do mar, e por isso a água ferve abaixo de 100 °C.","a":true}$j$, $q$Verdadeiro: menos ar em cima, menos pressão; a água ferve mais cedo e o feijão demora a cozinhar.$q$, 2);
select public.fj_seed_q('fis', 'fis:hidrostatica', 'fis:hidrostatica:1', 4, 'bank', $q$Complete a frase sobre o gelo$q$, $j${"parts":["O gelo flutua na água porque sua densidade é "," que a da água; já uma pedra afunda porque sua densidade é ","."],"a":["menor","maior"],"extra":["igual","nula"]}$j$, $q$Flutua o que é menos denso que o líquido; afunda o que é mais denso.$q$, 1);
select public.fj_seed_q('fis', 'fis:hidrostatica', 'fis:hidrostatica:1', 5, 'match', $q$Associe a situação ao conceito de pressão$q$, $j${"pairs":[["Salto fino afunda no gramado","Área pequena, pressão grande"],["Barragem mais grossa na base","Pressão cresce com a profundidade"],["Canudo que puxa o suco","Pressão atmosférica empurra o líquido"],["Pneu largo de trator","Área grande, pressão pequena no solo"]]}$j$, $q$Pressão é força distribuída em área; o cotidiano está cheio de exemplos.$q$, 2);
-- fis:hidrostatica:2 · Empuxo e Pascal
select public.fj_seed_q('fis', 'fis:hidrostatica', 'fis:hidrostatica:2', 0, 'mc', $q$Pelo princípio de Arquimedes, o empuxo sobre um corpo mergulhado é igual:$q$, $j${"opts":["Ao peso do líquido deslocado pelo corpo","Ao peso do corpo","À massa do corpo vezes a velocidade","À pressão no fundo do recipiente"],"a":0}$j$, $q$Quanto mais líquido o corpo desloca, maior a força para cima que ele recebe.$q$, 2);
select public.fj_seed_q('fis', 'fis:hidrostatica', 'fis:hidrostatica:2', 1, 'mc', $q$Um navio de aço flutua, mas uma bola de aço afunda, porque o navio:$q$, $j${"opts":["Tem o casco oco, deslocando muita água e recebendo grande empuxo","É feito de aço mais leve","Está sempre em movimento","Tem motores que o empurram para cima"],"a":0}$j$, $q$O volume do casco faz a densidade média do navio ficar menor que a da água.$q$, 2);
select public.fj_seed_q('fis', 'fis:hidrostatica', 'fis:hidrostatica:2', 2, 'mc', $q$No elevador hidráulico de oficina, uma força pequena levanta um carro porque:$q$, $j${"opts":["A pressão se transmite igualmente pelo líquido e age em um pistão de área maior","O óleo é mais leve que o ar","O carro perde peso dentro do óleo","O pistão pequeno gira mais rápido"],"a":0}$j$, $q$Princípio de Pascal: mesma pressão, área 10 vezes maior, força 10 vezes maior.$q$, 2);
select public.fj_seed_q('fis', 'fis:hidrostatica', 'fis:hidrostatica:2', 3, 'tf', $q$Julgue a afirmação sobre o empuxo$q$, $j${"stmt":"Um objeto parece mais leve dentro da água porque o empuxo age para cima, contra o peso.","a":true}$j$, $q$Verdadeiro: por isso é fácil levantar uma pessoa na piscina.$q$, 1);
select public.fj_seed_q('fis', 'fis:hidrostatica', 'fis:hidrostatica:2', 4, 'order', $q$Ordene os passos do funcionamento do freio hidráulico$q$, $j${"items":["O pé aplica força no pedal","O pistão pequeno pressiona o fluido de freio","A pressão se transmite pelo fluido até as rodas","Os pistões maiores apertam as pastilhas contra o disco"]}$j$, $q$Pascal em ação: a pressão viaja pelo líquido e se multiplica em força nas rodas.$q$, 2);
select public.fj_seed_q('fis', 'fis:hidrostatica', 'fis:hidrostatica:2', 5, 'match', $q$Associe o fenômeno ao princípio que o explica$q$, $j${"pairs":[["Balão de ar quente sobe","Empuxo do ar sobre o balão menos denso"],["Submarino afunda ao encher tanques","Densidade média aumenta"],["Prensa hidráulica","Princípio de Pascal"],["Barômetro de Torricelli","Pressão atmosférica sustenta a coluna"]]}$j$, $q$Arquimedes, Pascal e Torricelli explicam os fluidos do dia a dia.$q$, 3);
-- fis:gravitacao:1 · Lei da gravitação
select public.fj_seed_q('fis', 'fis:gravitacao', 'fis:gravitacao:1', 0, 'mc', $q$Pela lei da gravitação de Newton, a força de atração entre dois corpos:$q$, $j${"opts":["Aumenta com as massas e diminui com o quadrado da distância","Independe da distância","Só existe entre planetas","Diminui com as massas"],"a":0}$j$, $q$F = G·M·m/d²: dobrar a distância reduz a força a um quarto.$q$, 2);
select public.fj_seed_q('fis', 'fis:gravitacao', 'fis:gravitacao:1', 1, 'mc', $q$Na Lua, a gravidade é cerca de 1/6 da terrestre. Um astronauta de 60 kg terá na Lua:$q$, $j${"opts":["Massa de 60 kg e peso cerca de 100 N","Massa de 10 kg e peso de 600 N","Massa de 60 kg e peso de 600 N","Massa de 10 kg e peso de 100 N"],"a":0}$j$, $q$A massa não muda; o peso (P = m·g) cai para 60 × 10/6 ≈ 100 N.$q$, 2);
select public.fj_seed_q('fis', 'fis:gravitacao', 'fis:gravitacao:1', 2, 'mc', $q$As marés são causadas principalmente:$q$, $j${"opts":["Pela atração gravitacional da Lua sobre as águas da Terra","Pelos ventos que empurram o mar","Pela rotação dos continentes","Pelo calor do Sol que dilata a água"],"a":0}$j$, $q$A Lua puxa a água mais próxima; o Sol também contribui, nas marés de sizígia.$q$, 1);
select public.fj_seed_q('fis', 'fis:gravitacao', 'fis:gravitacao:1', 3, 'tf', $q$Julgue a afirmação sobre a maçã e a Lua$q$, $j${"stmt":"Newton percebeu que a mesma força que faz a maçã cair mantém a Lua em órbita da Terra.","a":true}$j$, $q$Verdadeiro: a gravitação é universal, vale para maçãs, luas e galáxias.$q$, 1);
select public.fj_seed_q('fis', 'fis:gravitacao', 'fis:gravitacao:1', 4, 'bank', $q$Complete a frase sobre peso e massa$q$, $j${"parts":["A "," é a quantidade de matéria e não muda de lugar para lugar; o "," é a força da gravidade sobre o corpo e muda conforme o planeta."],"a":["massa","peso"],"extra":["densidade","volume"]}$j$, $q$Massa em kg é a mesma em qualquer planeta; peso em newtons depende da gravidade local.$q$, 1);
select public.fj_seed_q('fis', 'fis:gravitacao', 'fis:gravitacao:1', 5, 'order', $q$Ordene do menor para o maior peso de um objeto de 1 kg$q$, $j${"items":["Na Lua (g ≈ 1,6 m/s²)","Em Marte (g ≈ 3,7 m/s²)","Na Terra (g ≈ 9,8 m/s²)","Em Júpiter (g ≈ 25 m/s²)"]}$j$, $q$Mesmo 1 kg, pesos de 1,6 N, 3,7 N, 9,8 N e 25 N.$q$, 2);
